import java.io.Serializable;import java.math.BigDecimal;import java.time.LocalDateTime;
public class Venta implements Serializable {private static final long serialVersionUID=1L;private int idVenta,numero;private String cliente,comprobante,metodoPago,estado;private LocalDateTime fecha;private BigDecimal total;
public int getIdVenta(){return idVenta;}public void setIdVenta(int v){idVenta=v;}public int getNumero(){return numero;}public void setNumero(int v){numero=v;}public String getCliente(){return cliente;}public void setCliente(String v){cliente=v;}public String getComprobante(){return comprobante;}public void setComprobante(String v){comprobante=v;}public String getMetodoPago(){return metodoPago;}public void setMetodoPago(String v){metodoPago=v;}public String getEstado(){return estado;}public void setEstado(String v){estado=v;}public LocalDateTime getFecha(){return fecha;}public void setFecha(LocalDateTime v){fecha=v;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal v){total=v;}}